// Material Map01Panorama (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_imageSize: vec2f,
  p_filtered: f32,
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_image: texture_2d<f32>;
@group(2) @binding(2) var material_sampler: sampler;
const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = (in.uv * material.p_imageSize);
  let v1: vec2f = floor(v0);
  let v2: vec2f = (v1 + 0.5);
  let v3: vec2f = (v2 / material.p_imageSize);
  let v4: vec2f = vec2f(material.p_filtered);
  let v5: vec2f = mix(v3, in.uv, v4);
  let v6: f32 = v5.x;
  let v7: f32 = v5.y;
  let v8: f32 = material.p_imageSize.y;
  let v9: f32 = (0.5 / v8);
  let v10: f32 = (252.5 / v8);
  let v11: f32 = clamp(v7, v9, v10);
  let v12: vec2f = vec2f(v6, v11);
  let v13: vec4f = textureSample(tex_image, material_sampler, v12);
  let v14: vec3f = v13.xyz;
  let v15: f32 = v13.w;
  out.base_color = v14;
  out.alpha = v15;
  return out;
}
